changeSet.sql:
ALTER TABLE usuario ADD CONSTRAINT ck_usuario_telefone_normalizado
  CHECK (telefone IS NULL OR telefone ~ '^[+]55[1-9][0-9]([2-5][0-9]{7}|9[0-9]{8})$');
ALTER TABLE usuario ADD CONSTRAINT ck_usuario_telefone_verificado
  CHECK (telefone_verificado_em IS NULL OR telefone IS NOT NULL);

rollback.sql:
DO $$ BEGIN
    IF EXISTS (SELECT 1 FROM usuario WHERE nome IS NOT NULL OR telefone IS NOT NULL) THEN
        RAISE EXCEPTION 'Exporte e preserve os dados cadastrais antes de reverter.';
    END IF;
END $$;

changeSet.sql:
CREATE TABLE usuario_desafio_telefone (
    id UUID PRIMARY KEY,
    id_usuario UUID NOT NULL REFERENCES usuario(id) ON DELETE RESTRICT,
    telefone VARCHAR(16) NOT NULL,
    codigo_hash VARCHAR(100),
    criado_em TIMESTAMPTZ NOT NULL,
    expira_em TIMESTAMPTZ NOT NULL,
    enviado BOOLEAN NOT NULL,
    tentativas INTEGER NOT NULL CHECK (tentativas BETWEEN 0 AND 5)
);
CREATE INDEX ix_desafio_telefone_usuario ON usuario_desafio_telefone (id_usuario, criado_em DESC);
CREATE INDEX ix_desafio_telefone_numero ON usuario_desafio_telefone (telefone, criado_em DESC);
CREATE INDEX ix_desafio_telefone_criacao ON usuario_desafio_telefone (criado_em);
